
import { useEffect, useState } from 'react'
import { supabase } from './services/supabase'

type Attendance = {
  id: string
    teacher_id: string
      attendance_date: string
        check_in_at: string
          status: string
          }

          type Teacher = {
            id: string
              full_name: string
              }
              type LeaveRecord = {
                      teacher_id: string
                        leave_type: string
                          start_date: string
                            end_date: string
                              status: string
                              }

              type Props = {
                role: string
                }

                export default function AttendanceHistory({ role }: Props) {
                  const [records, setRecords] = useState<Attendance[]>([])
                    const [teacherNames, setTeacherNames] = useState<Record<string, string>>({})
                      const [loading, setLoading] = useState(true)
                        const [message, setMessage] = useState('')
                        const [leaveRecords, setLeaveRecords] = useState<LeaveRecord[]>([])
                        const [selectedMonth, setSelectedMonth] = useState(
                                new Date().toLocaleString('sv-SE', {
                                    timeZone: 'Asia/Jakarta'
                                      }).slice(0, 7)
                                      )

                          async function loadHistory() {
                              setLoading(true)
                                  setMessage('')

                                      try {
                                            const { data, error } = await supabase
                                                    .from('attendance_records')
                                                            .select('id, teacher_id, attendance_date, check_in_at, status')
                                                                    .order('attendance_date', { ascending: false })
                                                                            .order('check_in_at', { ascending: false })

                                                                                  if (error) throw error

                                                                                        const rows = (data || []) as Attendance[]
                                                                                              setRecords(rows)

                                                                                                    if (role !== 'teacher') {
                                                                                                            const { data: users, error: usersError } = await supabase
                                                                                                                .from('users')
                                                                                                                    .select('id, full_name')
                                                                                                                        .eq('role', 'teacher')
                                                                                                                            .order('full_name', { ascending: true })

                                                                                                                              if (usersError) throw usersError

                                                                                                                                const names: Record<string, string> = {}

                                                                                                                                  ;((users || []) as Teacher[]).forEach(user => {
                                                                                                                                      names[user.id] = user.full_name
                                                                                                                                        })

                                                                                                                                          setTeacherNames(names)
                                                                                                                                          const { data: leaves, error: leavesError } = await supabase
                                                                                                                                            .from('leave_requests')
                                                                                                                                              .select('teacher_id, leave_type, start_date, end_date, status')
                                                                                                                                                .eq('status', 'approved')

                                                                                                                                                if (leavesError) throw leavesError

                                                                                                                                                setLeaveRecords((leaves || []) as LeaveRecord[])
                                                                                                                                          }
                                                                                                    
                                                                                                                                                                                                
                                                                                                                                                                                                                                                                    } catch (error: any) {
                                                                                                                                                                                                                                                                          setMessage(error.message || 'Gagal memuat riwayat absensi.')
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                  setLoading(false)
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                      useEffect(() => {
                                                                                                                                                                                                                                                                                          loadHistory()
                                                                                                                                                                                                                                                                                            }, [])

                                                                                                                                                                                                                                                                                              function formatDate(value: string) {
                                                                                                                                                                                                                                                                                                  return new Date(value + 'T00:00:00+07:00').toLocaleDateString('id-ID', {
                                                                                                                                                                                                                                                                                                        day: 'numeric',
                                                                                                                                                                                                                                                                                                              month: 'long',
                                                                                                                                                                                                                                                                                                                    year: 'numeric',
                                                                                                                                                                                                                                                                                                                          timeZone: 'Asia/Jakarta'
                                                                                                                                                                                                                                                                                                                              })
                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                  function formatTime(value: string) {
                                                                                                                                                                                                                                                                                                                                      return new Date(value).toLocaleTimeString('id-ID', {
                                                                                                                                                                                                                                                                                                                                            hour: '2-digit',
                                                                                                                                                                                                                                                                                                                                                  minute: '2-digit',
                                                                                                                                                                                                                                                                                                                                                        timeZone: 'Asia/Jakarta'
                                                                                                                                                                                                                                                                                                                                                            }) + ' WIB'
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                          const filteredRecords = records.filter((record) => {
                                                                                                                                                                                                                                                                  return record.attendance_date.startsWith(selectedMonth)
                                                                                                                                                                                                                                                                  })

                                                                                                                                                                                                                                                                  const groupedRecords = Object.entries(teacherNames)
                                                                                                                                                                                                                                                                    .sort(([, nameA], [, nameB]) => {
                                                                                                                                                                                                                                                                        return nameA.localeCompare(nameB, 'id')
                                                                                                                                                                                                                                                                          })
                                                                                                                                                                                                                                                                            .map(([teacherId]) => {
                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                      teacherId,
                                                                                                                                                                                                                                                                                            teacherRecords: filteredRecords.filter((record) => {
                                                                                                                                                                                                                                                                                                    return record.teacher_id === teacherId
                                                                                                                                                                                                                                                                                                          })
                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                })

                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                    <section style={{
                                                                                                                                                                                                                                                                                                                                                                          background: '#ffffff',
                                                                                                                                                                                                                                                                                                                                                                                padding: '20px',
                                                                                                                                                                                                                                                                                                                                                                                      borderRadius: '12px',
                                                                                                                                                                                                                                                                                                                                                                                            marginBottom: '20px',
                                                                                                                                                                                                                                                                                                                                                                                                  border: '1px solid #e5e7eb'
                                                                                                                                                                                                                                                                                                                                                                                                      }}>
                                                                                                                                                                                                                                                                                                                                                                                                            <h2>Riwayat Absensi</h2>
                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ marginBottom: '18px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                    <label style={{
                                                                                                                                                                                                                                                                                                                                                                                                                        display: 'block',
                                                                                                                                                                                                                                                                                                                                                                                                                            marginBottom: '8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                fontWeight: 'bold'
                                                                                                                                                                                                                                                                                                                                                                                                                                  }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                      Pilih Periode Absensi
                                                                                                                                                                                                                                                                                                                                                                                                                                        </label>

                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                              type="month"
                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={selectedMonth}
                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={(e) => setSelectedMonth(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                          style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: '10px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      border: '1px solid #cbd5e1',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: '8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  width: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        maxWidth: '250px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fontSize: '15px'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                          onClick={loadHistory}
                                                                                                                                                                                                                                                                                                                                                                                                                                  disabled={loading}
                                                                                                                                                                                                                                                                                                                                                                                                                                          style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: '#166534',
                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: 'white',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: '10px 16px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: '8px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      marginBottom: '15px'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {loading ? 'Memuat...' : 'Muat Ulang'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {loading && <p>Memuat riwayat absensi...</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {message && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p style={{ color: '#b91c1c' }}>{message}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {!loading && !message && records.length === 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>Belum ada riwayat absensi.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     {!loading && role === 'teacher' && filteredRecords.map(record => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 key={record.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           borderTop: '1px solid #e5e7eb',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 padding: '14px 0'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <strong>Riwayat Absensi Saya</strong>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               <p>Tanggal: {formatDate(record.attendance_date)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <p>Waktu: {formatTime(record.check_in_at)}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <p style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             color: record.status === 'present' ? '#166534' : '#b45309',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   fontWeight: 'bold'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             Status: {record.status === 'present'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ? 'HADIR'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             : record.status === 'late'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ? 'TERLAMBAT'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 : record.status.toUpperCase()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ))}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       {!loading && role !== 'teacher' && groupedRecords.map(({ teacherId, teacherRecords }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const totalHadir = teacherRecords.filter(item => item.status === 'present').length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const totalTerlambat = teacherRecords.filter(item => item.status === 'late').length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const teacherLeaves = leaveRecords.filter(item => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       item.teacher_id === teacherId &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           item.status === 'approved' &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               item.start_date <= selectedMonth + '-31' &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   item.end_date >= selectedMonth + '-01'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const totalIzin = teacherLeaves.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       item => item.leave_type === 'permission'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       ).length

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const totalSakit = teacherLeaves.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         item => item.leave_type === 'sick'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ).length
                                                                                                

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       key={teacherId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     border: '1px solid #e5e7eb',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             borderRadius: '10px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     padding: '15px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             marginBottom: '15px'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <h3 style={{ marginTop: 0, color: '#123b63' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     {teacherNames[teacherId] || 'Guru'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </h3>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <p>Total kehadiran: <strong>{teacherRecords.length} catatan</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <p>Hadir: <strong style={{ color: '#166534' }}>{totalHadir} hari</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <p>Terlambat: <strong style={{ color: '#b45309' }}>{totalTerlambat} hari</strong></p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <p>Izin disetujui: {totalIzin} pengajuan</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <p>Sakit disetujui: {totalSakit} pengajuan</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   <div style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           borderTop: '1px solid #e5e7eb',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   marginTop: '12px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           paddingTop: '10px'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         <strong>Rincian Absensi</strong>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         {teacherRecords.length === 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <p style={{ color: '#64748b' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Belum ada catatan absensi.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 {teacherRecords.map(record => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       key={record.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 padding: '10px 0',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               borderBottom: '1px solid #f1f5f9'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 <p style={{ margin: '5px 0' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               Tanggal: {formatDate(record.attendance_date)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       <p style={{ margin: '5px 0' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     Waktu: {formatTime(record.check_in_at)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             <p style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           margin: '5px 0',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         color: record.status === 'present' ? '#166534' : '#b45309',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       fontWeight: 'bold'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Status: {record.status === 'present'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 ? 'HADIR'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 : record.status === 'late'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ? 'TERLAMBAT'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     : record.status.toUpperCase()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          